<?php
namespace App\Http\Controllers;
use Illuminate\Routing\Controller;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use App\Services\Support;
class AccountController extends Controller {
 public function address(Request $r){$v=$r->validate(['recipient'=>'required|string|max:150','phone'=>['required','regex:/^09[0-9]{9}$/'],'region'=>'nullable|string|max:120','province'=>'required|string|max:120','city'=>'required|string|max:120','barangay'=>'required|string|max:120','street'=>'required|string|max:200','postal_code'=>['required','regex:/^[0-9]{4}$/']]);\App\Services\Geography::validate($v);$u=auth()->user();$old=\App\Services\Municipalities::address($u->id);if(in_array($u->role,['sorting_center','rider'])&&$old&&!\App\Services\Municipalities::matches($old,(object)$v))Support::fail('city','Your registered service municipality cannot be changed here. Ask the logistics administrator to review your territory.');unset($v['region']);DB::transaction(function()use($v,$old,$u){if($old)DB::table('addresses')->where('id',$old->id)->where('user_id',$u->id)->update($v+['updated_at'=>now()]);else DB::table('addresses')->insert($v+['user_id'=>$u->id,'is_default'=>1,'created_at'=>now(),'updated_at'=>now()]);});return back()->with('success','Address updated.');}
 public function status(Request $r,int $id){$v=$r->validate(['status'=>'required|in:active,archived,suspended,banned','reason'=>'required|string|min:5|max:300']);$roles=auth()->user()->role==='admin'?['buyer','seller']:['sorting_center','rider'];abort_unless(in_array(auth()->user()->role,['admin','logistics_admin']),403);abort_if($id===auth()->id(),422);
 DB::transaction(function()use($id,$v,$roles){$u=DB::table('users')->where('id',$id)->whereIn('role',$roles)->lockForUpdate()->first();abort_unless($u,404);abort_if($u->account_status==='banned',422,'Banned accounts are permanent and cannot be restored or changed.');DB::table('account_appeals')->where('user_id',$id)->where('status','pending')->update(['status'=>'closed','resolution'=>'Account state changed by administrator.','updated_at'=>now()]);DB::table('users')->where('id',$id)->update(['account_status'=>$v['status'],'account_status_reason'=>$v['reason'],'active'=>$v['status']==='active','online'=>0,'api_token_expires_at'=>null,'remember_token'=>null,'updated_at'=>now()]);Support::audit('account-status','user',$id,$u,$v,$v['reason']);Support::notify([$id],'Your account is '.$v['status'].': '.$v['reason']);Support::email($id,'LokaShop account status','Your account is '.$v['status'].'. '.$v['reason']);});return back()->with('success','Account status updated. Records and order history were retained.');}
}
